type Contract = { primaryMetric: { name: string; objective: "maximize" | "minimize"; minimumEffect: number }; baselineMetrics: Record<string, number>; roundWidths?: number[]; stopConditions?: { target?: number; maximumNoProgressRounds?: number }; execution: { runner: "native" | "wsl2"; distribution?: string | null; command: string[]; resultPath: string; timeoutSeconds: number; checkpointCommand?: string[] | null; usesGpu?: boolean } };
