      const completion = records.find((record) => record.$schema === schemaUri("autoresearch-completion-packet")); if (completion) { this.research.transitionAutoresearch(project.projectId, autoresearchId, execution.version, "completed", `autoresearch-completed:${autoresearchId}`); return; }
      const round = [...records].reverse().find((record) => record.$schema === schemaUri("autoresearch-round") && validateRecord(schemaUri("autoresearch-round"), record as unknown as JsonValue).ok);
