    this.rehydrateTree(execution.value, records, parentCommit).add({ experimentId: proposal.experimentId, parentExperimentId: proposal.parentExperimentId, ideaFingerprint: proposal.novelty.ideaFingerprint, attemptFingerprint: sha256({ experimentId: proposal.experimentId, proposalId: proposal.proposalId }), evaluationContractHash: execution.value.evaluationContractHash, branch: branchName(execution.entityId, proposal.experimentId), evaluatedCommit: null, depth: round, state: "proposed", reviewId: null, reviewerAgentId: null, guardrailsPass: null });
