function same(left: string[] | undefined, right: string[]): boolean { return Boolean(left && left.length === right.length && left.every((value, index) => value === right[index])); }
function git(cwd: string, args: string[]): string { const result = spawnSync("git", ["-C", cwd, ...args], { encoding: "utf8", windowsHide: true }); if (result.status !== 0) throw new Error(result.stderr.trim() || `git ${args[0]} failed`); return result.stdout.trim(); }
function postflight(worktree: string, packet: TaskPacket, record: JsonValue): string[] { const parsed = validateRecord(schemaUri("general-worker-completion"), record); if (!parsed.ok) return parsed.errors.map((error) => `${error.pointer} ${error.message}`); const value = parsed.value as unknown as { taskOutcome: string; readyForReview: boolean; readyForDeterministicPostflight: boolean; codeChanges: { startingCommit: string; endingCommit: string; changedPaths: string[]; branch: string }; commands: Array<{ exitCode: number | null }>; criteria: Array<{ criterionId: string; workerClaim: string; validatorRunIds: string[] }> }; const issues: string[] = []; if (value.taskOutcome !== "completed" || !value.readyForReview || !value.readyForDeterministicPostflight) issues.push("completion is not postflight-ready"); issues.push(...validateGitCompletion(worktree, packet.workspace, value.codeChanges)); if (value.commands.some((command) => command.exitCode !== 0)) issues.push("a declared validator failed"); for (const criterion of packet.acceptanceCriteria) if (!value.criteria.some((entry) => entry.criterionId === criterion.criterionId && entry.workerClaim === "satisfied" && entry.validatorRunIds.length)) issues.push(`criterion ${criterion.criterionId} lacks a passing validator`); return [...new Set(issues)]; }
function reviewPasses(review: ReviewVerdict, request: ReviewRequest, reviewerId: string): boolean { if (!validateRecord(schemaUri("review-verdict"), review as unknown as JsonValue).ok || review.reviewId !== request.reviewId || review.reviewRequestId !== request.reviewRequestId || review.reviewType !== request.reviewType || review.reviewerAgentId !== reviewerId || review.independenceCheck !== "pass" || review.verdict !== "PASS" || review.target?.targetType !== request.target.targetType || review.target.targetId !== request.target.targetId || review.target.targetVersion !== request.target.targetVersion) return false; if (!request.criteria.every((criterion) => review.criteria?.some((entry) => entry.criterionId === criterion.criterionId && entry.status === "PASS"))) return false; return request.requiredArtifactIds.every((id) => review.reviewedArtifactIds?.includes(id)) && request.requiredEvidenceIds.every((id) => review.reviewedEvidenceIds?.includes(id)); }
function event(execution: AutoresearchProjection, type: string, payload: JsonValue): EventDraft { return { $schema: schemaUri("event"), schemaVersion: 1, retention: "persistent", type, source: "autoresearch_supervisor", scope: { projectId: execution.projectId, missionId: execution.missionId, directionId: execution.directionId, autoresearchId: execution.autoresearchId, experimentId: null, runId: null, jobId: null, agentId: null }, correlationId: execution.autoresearchId, causationId: null, payload }; }
